Description.TranslatedText:
Set to "ASIAN - MIXED ASIAN RACE" if DM.RACE = "ASIAN" and SUPPDM.QVAL is not missing where SUPPDM.QNAM = "RACEOR1" and SUPPDM.QNAM = "RACEOR2";
else set to "WHITE - MIXED WHITE RACE" if DM.RACE = "WHITE" and SUPPDM.QVAL is not missing where SUPPDM.QNAM = "RACEOR1" and SUPPDM.QNAM = "RACEOR2"; 
else set to "MIXED RACE" if DM.RACE = "MULTIPLE";
if DM.RACE in ("WHITE" ASIAN") and missing(SUPPDM.QVAL) where SUPPDM.QNAM = "RACEOR1" then for ADSL.RACE = "WHITE" set ADSL.ARACE = WHITE - NOT REPORTED/OTHER" and for ADSL.RACE = "ASIAN" set ADSL.ARACE = "ASIAN - NOT REPORTED/OTHER" else set to SUPPDM.QVAL where SUPPDM.QNAM = "RACEOR1"
